    // Compute eigenvalues and eigenvectors
    rocsolver_dsyevdj(handle, rocblas_evect_original, rocblas_fill_upper,
                      n, d_A, lda, d_D, d_info);

    // Copy results back
    std::vector<double> h_D(n);
